const themeDescriptions={'All':'Every person remembers rain differently.','Working in the Rain':'Travel, income, plans, and responsibility shift when rain arrives.','Shelter & Care':'Stations, shops, and temporary shelter make brief acts of care visible.','Living with Humidity':'Moisture enters flowers, paper, piano keys, and homes.','Sounds & Landscapes':'Listen to rain on plants, buildings, water, and city streets.','Growing Up & Belonging':'Rain connects childhood, family, growing up, and memories of leaving Guangdong.'};
const rainObjects=[
  {slug:'dehumidifier',name:'Dehumidifier',category:'Indoor Humidity',image:'assets/rain-objects/除湿机.jpg',hook:'Invisible moisture collects in a visible tank.',condition:'During humid spring weather, warm moist air meets walls and floors that remain cool enough for water to condense. Rooms appear to sweat, and clothes become harder to dry.',everyday:'Dehumidifiers are often placed in bedrooms, living rooms, or laundry areas to reduce indoor relative humidity. Closing doors and windows and emptying the tank regularly helps the machine work effectively.',working:'A common compressor dehumidifier draws air across a cold coil. Water condenses on the coil and drains into a tank; the air then passes a warmer coil before returning to the room.',meaning:'The machine turns an invisible environmental change into a rising water level. Humidity moves from a sensation to something that can be observed and managed.'},
  {slug:'dry-box',name:'Dry Box',category:'Storage & Care',image:'assets/rain-objects/防潮箱.jpg',hook:'Instead of drying a whole room, protect one small and important space.',condition:'Even without direct rain, cameras can be damaged by sustained humidity. Dust and moisture raise the risk of fungus on lenses, while paper, electronics, and collections also suffer.',everyday:'A simple dry box seals cameras, lenses, or other sensitive objects with desiccant and a hygrometer. Electronic dry cabinets actively regulate the humidity inside.',working:'The seal slows humid air entering, silica gel adsorbs moisture, and the hygrometer shows the internal condition. Opening the door exchanges air, so stability also depends on limited access and regular checks.',meaning:'A dry box does not fight the whole season. It concentrates care inside one container and creates a controlled microclimate for objects worth keeping.'},
  {slug:'slippers',name:'Slippers',category:'Footwear & Ground',image:'assets/rain-objects/拖鞋.jpg',hook:'A rainy-day choice can begin with the most ordinary pair of shoes.',condition:'Heat, humidity, and sudden showers expose footwear to puddles, wet floors, and slow drying. Once absorbent linings are soaked, recovery takes even longer.',everyday:'Open plastic or rubber slippers are easy to put on, rinse, and dry. They appear at doorways, in bathrooms and dormitories, and across everyday rainy journeys.',working:'Sole material, tread depth, wear, and the ground all affect friction. Treads can give surface water a route away, but no slipper can guarantee grip on a wet floor.',meaning:'Materials have changed from Lingnan wooden clogs to modern plastic slippers, yet the choice still reflects heat, humidity, easy cleaning, and quick recovery.'},
  {slug:'herbal-tea',name:'Herbal Tea',category:'Food & Tradition',image:'assets/rain-objects/凉茶.jpg',hook:'Weather becomes a bodily feeling—and is brewed into an everyday drink.',condition:'Lingnan heat and humidity affect more than buildings and objects; they enter the language people use for bodily comfort. Traditional ideas of “heat” and “dampness” are not the same as thermometer and hygrometer readings.',everyday:'Cantonese herbal tea combines different plant materials in different recipes, brewed at home or in shops. There is no single formula; flavour, preparation, and customary use vary with local knowledge.',working:'Four recipes show how different plant materials are combined with different traditional intentions. The archive presents these as cultural knowledge rather than medical advice.',meaning:'Herbal tea connects local climate, inherited knowledge, taste memory, and neighbourhood life. It also reminds us that not every lived experience needs to be reduced to a physical formula.'},
  {slug:'qilou',name:'Qilou Arcades',category:'Architecture & Streets',image:'assets/rain-objects/骑楼.jpg',hook:'When the upper floor steps outward, the street gains a sheltered path.',condition:'Strong sun and frequent rain interrupt walking and street activity. One umbrella protects one person; a continuous arcade can protect a whole section of city life.',everyday:'The upper floor projects above the pavement on columns, while shops sit behind the colonnade. People can walk, pause, and shop under cover as the weather changes.',working:'The projection blocks some direct sun and intercepts rain over the walkway. Columns connect the shelter, while orientation, scale, wind, and neighbouring buildings affect actual comfort.',meaning:'Qilou place housing, commerce, and public walking space in one section. They are not simply awnings, but an arrangement that helps the city continue through hot, wet weather.'}
];
const rainObjectsZh={
  dehumidifier:{name:'除湿机',category:'室内湿度',hook:'看不见的水汽，最终聚成水箱里可见的水。',condition:'回南天里，暖湿空气遇到仍然较冷的墙面和地面，水汽容易凝结。房间像在“出汗”，衣物也更难晾干。',everyday:'除湿机常放在卧室、客厅或晾衣区，用来降低室内相对湿度。关好门窗、定期清空水箱，能够帮助机器更有效地工作。',working:'常见的压缩式除湿机让空气经过低温盘管，水汽在盘管表面凝结并流入水箱；空气随后经过较暖的盘管，再回到室内。',meaning:'机器把不可见的环境变化转化为不断上升的水位，让湿度从一种感觉变成可以观察和管理的东西。'},
  'dry-box':{name:'防潮箱',category:'储存与保护',hook:'与其让整个房间变干，不如先保护一个小而重要的空间。',condition:'即使没有直接淋雨，持续的湿度也可能损害相机。灰尘和水汽会增加镜头长霉的风险，纸张、电子设备和收藏品也会受到影响。',everyday:'简易防潮箱会把相机、镜头等敏感物品与干燥剂和湿度计一同密封保存；电子防潮柜则会主动调节内部湿度。',working:'密封结构减慢湿空气进入，硅胶吸附水分，湿度计显示箱内状态。每次开箱都会交换空气，因此稳定性也取决于少开箱和定期检查。',meaning:'防潮箱并不与整个雨季对抗，而是把照料集中在一个容器里，为值得保存的物品建立一个可控制的小气候。'},
  slippers:{name:'拖鞋',category:'脚下与地面',hook:'面对雨天的选择，可以从最普通的一双鞋开始。',condition:'炎热、潮湿和突如其来的阵雨，让鞋子经常面对水洼、湿地面和漫长的晾干时间。吸水内衬一旦浸湿，恢复会更慢。',everyday:'塑料或橡胶拖鞋容易穿脱、冲洗和晾干。它们出现在门口、浴室、宿舍，也陪人走过日常的雨路。',working:'鞋底材料、纹路深度、磨损程度和地面状况共同影响摩擦。纹路可以为表面水提供排出的通道，但任何拖鞋都不能保证完全防滑。',meaning:'从岭南木屐到现代塑料拖鞋，材料变了，但选择仍然回应着炎热、潮湿、容易清洗和快速恢复。'},
  'herbal-tea':{name:'凉茶',category:'饮食与传统',hook:'天气成为身体的感受，也被煮进一杯日常饮料。',condition:'岭南的湿热不只进入建筑和物件，也进入人们描述身体感受的语言。传统所说的“热”和“湿”，并不等同于温度计和湿度计的读数。',everyday:'广东凉茶把不同植物材料组合成不同配方，在家里或凉茶铺中煮制。它没有唯一公式，味道、做法和传统用途都随地方知识而变化。',working:'四个配方展示不同植物材料如何与不同的传统意图组合。本档案把它们作为文化知识呈现，而不是医疗建议。',meaning:'凉茶连接地方气候、传承知识、味觉记忆和街坊生活，也提醒我们，并非每一种生活经验都需要被还原成物理公式。'},
  qilou:{name:'骑楼',category:'建筑与街道',hook:'当楼层向外挑出，街道便多了一条有遮蔽的路径。',condition:'强烈日照和频繁降雨会打断步行与街道活动。一把伞只能保护一个人，连续骑楼却能保护一整段城市生活。',everyday:'上层建筑由柱子支撑并挑出在人行道上方，商铺位于柱廊后方。天气变化时，人们仍能在遮蔽下行走、停留和购物。',working:'挑出的楼层遮挡部分直射阳光，也拦截落向步行空间的雨；柱子把遮蔽连成一线，而朝向、尺度、风和相邻建筑都会影响实际舒适度。',meaning:'骑楼把居住、商业与公共步行空间放在同一个剖面中。它不只是雨棚，而是一种让城市在炎热潮湿天气中继续运转的空间安排。'}
};
