  {title:'Drier air returns',detail:'The dehumidified air passes the warm condenser coil before the outlet fan sends it back into the room.',effect:'The returning air is drier and is often slightly warmer than the air that entered.',parts:['warm-coil','outlet']},
  {title:'The refrigeration loop repeats',detail:'A compressor circulates refrigerant through the evaporator and condenser, keeping one coil cold and the other warm.',effect:'That temperature difference lets the air path keep removing moisture.',parts:['compressor','refrigerant','cold-coil','warm-coil']}
