  {title:'Maintain the microclimate',detail:'Open the box briefly, check the reading, and dry or replace saturated desiccant when humidity begins to rise.',effect:'Protection comes from a repeated routine: seal, observe, renew, and return the equipment to a controlled microclimate.',parts:['seal','desiccant','hygrometer']}
