const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>/^https:\/\//.test(s)?esc(s):'#';
const regexEscape=s=>String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
function firstPersonEnglish(text,name){
  let value=String(text||'');
  if(name){const n=regexEscape(name);value=value.replace(new RegExp(n+'[’\\\']s','g'),'my').replace(new RegExp('\\b'+n+'\\b','g'),'I')}
  value=value.replace(/((?:student|young woman|woman|girl|daughter|mother|grandmother|father|grandfather|husband|wife|boy|child)[^.!?]{0,52})\b(she|he|her|him|his)\b/gi,(match,prefix,pronoun)=>prefix+'__THIRD_'+pronoun.toUpperCase()+'__');
  value=value.replace(/(\bI\b[^.!?]{0,100}\b(?:lent|gave|handed|told|helped|saw|found|pulled|guided|offered|brought|caught)\s+)\b(her|him)\b/gi,(match,prefix,pronoun)=>prefix+'__THIRD_'+pronoun.toUpperCase()+'__');
  const possessiveHer='daughter|first|husband|roommates|child|memory|mother|pace|joints|sleep|shoes|permission|dress|eyes|family|trousers|suit|calves|fringe|soles|hands|clothes|window|work|seat|temper';
  value=value.replace(/\b(?:His|Her)\b/g,'My').replace(/\bhis\b/g,'my').replace(new RegExp('\\bher\\b(?=\\s+(?:'+possessiveHer+')\\b)','gi'),'my').replace(/\bher\b/gi,'me').replace(/\bhim\b/gi,'me').replace(/\b(?:He|She)\b/g,'I').replace(/\b(?:he|she)\b/g,'I');
  value=value.replace(/__THIRD_(SHE|HE|HER|HIM|HIS)__/g,match=>({__THIRD_SHE__:'she',__THIRD_HE__:'he',__THIRD_HER__:'her',__THIRD_HIM__:'him',__THIRD_HIS__:'his'})[match]);
  const verbs={is:'am',has:'have',does:'do',feels:'feel',remembers:'remember',says:'say',hopes:'hope',works:'work',keeps:'keep',carries:'carry',watches:'watch',thinks:'think',finds:'find',lives:'live',likes:'like',loves:'love',knows:'know',needs:'need',wants:'want',prefers:'prefer',waits:'wait',hears:'hear',notices:'notice',uses:'use',asks:'ask',avoids:'avoid',changes:'change',checks:'check',continues:'continue',earns:'earn',grows:'grow',listens:'listen',misses:'miss',moves:'move',observes:'observe',protects:'protect',removes:'remove',repeats:'repeat',runs:'run',schedules:'schedule',sees:'see',sets:'set',sits:'sit',spends:'spend',studies:'study',turns:'turn',visits:'visit'};
  const correctVerb=verb=>verbs[verb]||verb;
  value=value.replace(/\bI\s+([A-Za-z]+)\b/g,(match,verb)=>`I ${correctVerb(verb)}`)
    .replace(/\bI\s+(still|also|often|now|especially|sometimes|usually|already|once)\s+([A-Za-z]+)\b/g,(match,adverb,verb)=>`I ${adverb} ${correctVerb(verb)}`)
    .replace(/\bI([^.!?;]{0,90}?)\band\s+(watches|remembers|sees|hears|hopes|thinks|checks|keeps|uses|prefers|likes|needs|wants|sits|runs|works|continues|protects|observes|visits)\b/g,(match,middle,verb)=>`I${middle} and ${correctVerb(verb)}`)
    .replace(/\bI and my ([^,.;]+?)(?=\s+(?:carried|lifted|stood|entered|worked|found|opened|moved|walked|ran|were|are)\b)/gi,(match,people)=>`my ${people} and I`)
    .replace(/^my ([^,.;]+?) and I\b/, 'My $1 and I')
    .replace(/\b(my [^,.;]+? and I[^.!?]{0,70})\btheir\b/gi,'$1our')
    .replace(/\s{2,}/g,' ')
    .replace(/\b(make|makes|made|let|lets|help|helps|helped) I\b/g,'$1 me');
  return value;
}
function firstPersonChinese(text,name){
  let value=String(text||'');
  if(name)value=value.replaceAll(name+'的','我的').replaceAll(name,'我');
  value=value.replace(/((?:女生|女学生|女孩|女人|女儿|母亲|妈妈|乘客|顾客|游客|女同事|室友|妻子)[^。！？；]{0,28})她/g,'$1__FEMALE3__').replace(/((?:男生|男学生|男孩|男人|儿子|父亲|爸爸|乘客|顾客|游客|男同事|丈夫)[^。！？；]{0,28})他/g,'$1__MALE3__');
  value=value.replace(/(借给了?|交给了?|递给了?|告诉|帮助|看见|看到|扶起?|送给|交还给|对)她/g,'$1__FEMALE3__').replace(/(借给了?|交给了?|递给了?|告诉|帮助|看见|看到|扶起?|送给|交还给|对)他/g,'$1__MALE3__');
  return value.replaceAll('他的','我的').replaceAll('她的','我的').replace(/(?<![其吉])他/g,'我').replaceAll('她','我').replaceAll('__FEMALE3__','她').replaceAll('__MALE3__','他').replace(/(父亲[^。！？]{0,32}向)他/g,'$1我');
}
