function startRain(){
  const canvas=document.querySelector('#rain');if(!canvas)return;
  const ctx=canvas.getContext('2d');let w,h,last=performance.now();
  const drops=Array.from({length:90},()=>({x:Math.random(),y:Math.random(),speed:.17+Math.random()*.3,length:10+Math.random()*24}));
  function resize(){w=canvas.width=canvas.clientWidth;h=canvas.height=canvas.clientHeight}resize();window.addEventListener('resize',resize);
  const button=document.querySelector('.rain-toggle');function update(){if(!button)return;button.textContent='雨幕 · '+(rainEnabled?'开':'关');button.setAttribute('aria-pressed',String(rainEnabled))}update();if(button)button.onclick=()=>{rainEnabled=!rainEnabled;update()};
  function frame(now){if(!canvas.isConnected){window.removeEventListener('resize',resize);return}const dt=Math.min((now-last)/1000,.04);last=now;ctx.clearRect(0,0,w,h);if(rainEnabled&&!document.hidden){ctx.strokeStyle='rgba(205,235,255,.32)';ctx.lineWidth=.8;for(const d of drops){d.y+=d.speed*dt;if(d.y>1.08){d.y=-.1;d.x=Math.random()}ctx.beginPath();ctx.moveTo(d.x*w,d.y*h);ctx.lineTo(d.x*w-4,d.y*h+d.length);ctx.stroke()}}requestAnimationFrame(frame)}requestAnimationFrame(frame);
}

function startShapeRain(){
  const canvas=document.querySelector('#shape-rain');if(!canvas||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const ctx=canvas.getContext('2d');let w,h,last=performance.now();
  const drops=Array.from({length:165},()=>({x:Math.random(),y:Math.random(),speed:.15+Math.random()*.24,length:10+Math.random()*22,alpha:.14+Math.random()*.16}));
  function resize(){const ratio=Math.min(devicePixelRatio||1,2);w=innerWidth;h=innerHeight;canvas.width=w*ratio;canvas.height=h*ratio;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(ratio,0,0,ratio,0,0)}resize();window.addEventListener('resize',resize);
  function frame(now){if(!canvas.isConnected){window.removeEventListener('resize',resize);return}const dt=Math.min((now-last)/1000,.04);last=now;ctx.clearRect(0,0,w,h);if(!document.hidden){ctx.lineWidth=.7;for(const d of drops){d.y+=d.speed*dt;if(d.y>1.06){d.y=-.06;d.x=Math.random()}ctx.strokeStyle=`rgba(226,240,247,${d.alpha})`;ctx.beginPath();ctx.moveTo(d.x*w,d.y*h);ctx.lineTo(d.x*w-3,d.y*h+d.length);ctx.stroke()}}requestAnimationFrame(frame)}requestAnimationFrame(frame);
}

